	errPolicyOperationPayeeRequired      = strerror("operation and payee are required")
	errPolicyLimitsPositive              = strerror("limits must be positive")
	errPolicyApprovalThresholdNegative  = strerror("approval threshold must not be negative")
	errPolicyApprovalWaitNonPositive    = strerror("approval wait must be positive when approval is enabled")
